# Use dotnet to reflect on the types
result = subprocess.run(['dotnet', 'csharp', '-e', '''
using System.Reflection;
var asm = Assembly.LoadFrom(\"$HOME/.nuget/packages/xunit.v3.core/1.1.0/lib/net6.0/xunit.v3.core.dll\");
var t = asm.GetType(\"Xunit.v3.CollectionBehaviorAttribute\") ?? asm.GetType(\"Xunit.CollectionBehaviorAttribute\");
if (t != null) {
    Console.WriteLine(\"Type: \" + t.FullName);
    foreach(var c in t.GetConstructors()) Console.WriteLine(\"Ctor: \" + string.Join(\", \", c.GetParameters().Select(p => p.ParameterType.Name + \" \" + p.Name)));
    foreach(var p in t.GetProperties()) Console.WriteLine(\"Prop: \" + p.Name + \" (\" + p.PropertyType.Name + \")\");
} else {
    foreach(var tt in asm.GetExportedTypes().Where(x => x.Name.Contains(\"Collection\"))) Console.WriteLine(tt.FullName);
}
'''], capture_output=True, text=True)
print(result.stdout)
print(result.stderr[:500] if result.stderr else '')
"

