using System.Reflection;

var commonAsm = Assembly.LoadFrom(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/xunit.v3.common/1.1.0/lib/netstandard2.0/xunit.v3.common.dll"));
var coreAsm = Assembly.LoadFrom(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll"));

foreach (var asm in new[] { commonAsm, coreAsm }) {
    var cb = asm.GetType("Xunit.CollectionBehaviorAttribute") ?? asm.GetType("Xunit.v3.CollectionBehaviorAttribute");
    if (cb != null) {
        Console.WriteLine("Found: " + cb.FullName + " in " + asm.GetName().Name);
        foreach(var c in cb.GetConstructors()) Console.WriteLine("  Ctor: " + string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name)));
        foreach(var p in cb.GetProperties()) Console.WriteLine("  Prop: " + p.Name + " (" + p.PropertyType.Name + ")");
    }
    var tco = asm.GetType("Xunit.TestCaseOrdererAttribute") ?? asm.GetType("Xunit.v3.TestCaseOrdererAttribute");
    if (tco != null) {
        Console.WriteLine("Found: " + tco.FullName + " in " + asm.GetName().Name);
        foreach(var c in tco.GetConstructors()) Console.WriteLine("  Ctor: " + string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name)));
        foreach(var p in tco.GetProperties()) Console.WriteLine("  Prop: " + p.Name + " (" + p.PropertyType.Name + ")");
    }
}
EOF
