using System.Reflection;

var commonAsm = Assembly.LoadFrom(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/xunit.v3.common/1.1.0/lib/netstandard2.0/xunit.v3.common.dll"));
var coreAsm = Assembly.LoadFrom(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll"));

foreach (var asm in new[] { commonAsm, coreAsm }) {
    foreach (var t in asm.GetExportedTypes().Where(x => x.Name.Contains("CollectionBehavior") || x.Name.Contains("TestCaseOrderer"))) {
        Console.WriteLine("Type: " + t.FullName);
        foreach(var c in t.GetConstructors()) Console.WriteLine("  Ctor: " + string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name)));
        foreach(var p in t.GetProperties()) Console.WriteLine("  Prop: " + p.Name + " (" + p.PropertyType.Name + ")");
        Console.WriteLine();
    }
}
EOF
